package com.hashem.sms; import android.app.*;import android.content.*;import android.os.*;import android.telephony.*; public class HeadlessSmsSendService extends Service{public IBinder onBind(Intent i){return null;}public int onStartCommand(Intent i,int f,int id){if(i!=null){String a=i.getDataString(),b=i.getStringExtra(Intent.EXTRA_TEXT);if(a!=null&&b!=null)SmsManager.getDefault().sendTextMessage(a.replace("sms:","").replace("smsto:",""),null,b,null,null);}return START_NOT_STICKY;}}
